use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->SemioObjectSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let target=|i:usize|store::os_io::ArtifactRef{artifact_id:f["children"][i][0].as_str().unwrap().into(),dialect:store::os_io::ArtifactDialect{artifact_kind:f["children"][i][1].as_str().unwrap().into(),standard:f["children"][i][2].as_str().unwrap().into(),subset:f["children"][i][3].as_str().unwrap().into()}};let mut value=SemioObjectSnapshot::default();value.transform.translation.x=f["translation"][0].as_f64().unwrap();value.transform.translation.y=f["translation"][1].as_f64().unwrap();value.transform.translation.z=f["translation"][2].as_f64().unwrap();value.transform.scale.x=-1.0;value.transform.scale.y=2.0;value.transform.scale.z=0.5;value.brep=Some(store::ArtifactChild::new("brep-owned".into(),target(0)));value.mesh=Some(store::ArtifactChild::new("mesh-owned".into(),target(1)));value.properties=Some(store::ArtifactChild::new("value-owned".into(),target(2)));value}
fn project(value:&SemioObjectSnapshot)->SqliteDatabase{value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioObjectSnapshot,String>{SemioObjectSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_semio_object_placement_typed_handles_optional_presence_and_native_state(){let snapshot=fixture();let bytes=export_sqlite_database(&project(&snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(restored,snapshot);assert_eq!(<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&restored),<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&snapshot));assert_eq!(<SemioObjectSnapshot as store::ArtifactDsl>::print_dsl(&restored),<SemioObjectSnapshot as store::ArtifactDsl>::print_dsl(&snapshot));for mask in 0..8{let mut value=fixture();if mask&1==0{value.brep=None;}if mask&2==0{value.mesh=None;}if mask&4==0{value.properties=None;}assert_eq!(restore(&project(&value)).unwrap(),value);}assert_eq!(restore(&project(&SemioObjectSnapshot::default())).unwrap(),SemioObjectSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_object_rejects_child_reference_identity_shape_and_limits(){let original=project(&fixture());for change in 0..5{let mut db=original.clone();match change{0=>db.table_mut("semio_object_mesh_child").unwrap().rows[0].values[3]=SqliteValue::Integer(999),1=>db.table_mut("semio_object_reference").unwrap().rows[1].values[2]=SqliteValue::Text("foreign.artifact".into()),2=>db.table_mut("semio_object_reference").unwrap().rows[1].values[4]=SqliteValue::Text("brep".into()),3=>db.table_mut("semio_object_mesh_child").unwrap().rows[0].values[1]=SqliteValue::Integer(999),_=>{db.table_mut("semio_object_mesh_child").unwrap().rows.clear();}}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioObjectSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_object_independent_reference_join_and_transform_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=db.query('SELECT child_id,artifact_id,artifact_kind,standard,subset FROM semio_object_mesh_child JOIN semio_object_reference ON target_reference_id=semio_object_reference.id').get();if(r.child_id!=='mesh-owned'||r.artifact_id!==r.child_id||r.artifact_kind!=='s.stdio.semio'||r.standard!=='v1'||r.subset!=='mesh')throw Error('typed child');db.query('UPDATE semio_object_document SET translation_x=9.25,translation_x_ieee754_bits=4621396905123905536').run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();expected.transform.translation.x=9.25;assert_eq!(restored,expected);}

#[test]
fn sqlite_snapshot_semio_object_bare_owner_capability_native_payload_bridge(){let snapshot=fixture();let payload=store::os_io::IoPayload::Binary(<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&snapshot));let codec=store::ArtifactCodec::bare::<SemioObjectSnapshot,crate::standards::v1::subsets::object::schema::mutations::SemioObjectMutation>("s.stdio.semio.object");let provider=codec.snapshot_sqlite.expect("owner must publish typed SQLite capability");assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<SemioObjectSnapshot>()));let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"object".into()};let db=(provider.export)("s.stdio.semio.object",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let db=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=(provider.import)("s.stdio.semio.object",&dialect,db,SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(actual,payload);}

#[test]
fn sqlite_snapshot_semio_object_owned_numeric_bits_independent_sqlite(){use std::io::Write;use std::process::{Command,Stdio};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for(index,bits)in f["float64Bits"].as_array().unwrap().iter().enumerate(){let bits=u64::from_str_radix(bits.as_str().unwrap(),16).unwrap();let bits32=u32::from_str_radix(f["float32Bits"][index].as_str().unwrap(),16).unwrap();let v=f64::from_bits(bits);let _v32=f32::from_bits(bits32);let mut s=fixture();s.transform.translation.x=v;let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!((r.transform.translation.x).to_bits(),bits);assert_eq!(<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&s));}}

#[test]
fn sqlite_snapshot_semio_object_typed_exact_subset_dialect_and_document_guard(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let snapshot=fixture();let database=project(&snapshot);let dialect=|v:&serde_json::Value|store::os_io::ArtifactDialect{artifact_kind:v["artifactKind"].as_str().unwrap().into(),standard:v["standard"].as_str().unwrap().into(),subset:v["subset"].as_str().unwrap().into()};let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&database,&mut control).unwrap().diagnostics.is_empty());for invalid in f["invalidSqliteDialects"].as_array().unwrap(){assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(invalid),&database,&mut control).is_err());}let mut malformed=database;malformed.table_mut("semio_object_document").unwrap().rows[0].values[1]=SqliteValue::Text("other schema".into());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&malformed,&mut control).is_err());}

#[test]
fn sqlite_snapshot_semio_object_bounded_native_text_binary_admission() {
    let snapshot=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"object".into()};
    let provider=<SemioObjectSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let actual=(provider.import)("Semio native admission",&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
        let expected=match encoding{SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioObjectSnapshot as store::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&snapshot))};assert!(actual==expected,"controlled native output differs from the authored ordinary wire");
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
    }
    let large= SemioObjectSnapshot{schema:"x".repeat(100000),..snapshot};
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative||p.completed==0,SqliteDatabaseLimits::default())).is_err());
}

#[test]
fn sqlite_snapshot_semio_object_manual_native_child_fields_are_literal(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for id in f["literalChildIds"].as_array().unwrap(){let id=id.as_str().unwrap();let target=store::os_io::ArtifactRef{artifact_id:id.into(),dialect:store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"mesh".into()}};let child=store::ArtifactChild::<SemioMeshSnapshot>::new(id.into(),target.clone());let text=enc_child(&child);let parsed:store::ArtifactChild<SemioMeshSnapshot>=dec_child(&text).unwrap();assert_eq!(parsed.child_id,id);assert_eq!(parsed.target,target);let mut bytes=Vec::new();write_child(&mut bytes,&child);let parsed:store::ArtifactChild<SemioMeshSnapshot>=read_child(&mut store::ByteReader::new(&bytes)).unwrap();assert_eq!(parsed.child_id,id);assert_eq!(parsed.target,target);}}

#[test]
fn sqlite_snapshot_semio_object_controlled_native_child_materialization(){
    let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let length=f["nativeChildBytes"].as_u64().unwrap() as usize;let cancel_bytes=f["nativeChildCancelBytes"].as_u64().unwrap() as usize;
    let mut snapshot=fixture();let mesh=snapshot.mesh.as_mut().unwrap();mesh.child_id="a".repeat(length);mesh.target.artifact_id=mesh.child_id.clone();
    for payload in [store::os_io::IoPayload::Binary(<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&snapshot)),store::os_io::IoPayload::Text(<SemioObjectSnapshot as store::ArtifactDsl>::print_dsl(&snapshot))]{
        let restored=SemioObjectSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        assert_eq!(restored,snapshot);
        let mut canceled=false;
        let error=SemioObjectSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |event|{let cancel=event.phase==SqliteSnapshotPhase::DecodeNative&&event.total==length&&event.completed==cancel_bytes;canceled|=cancel;!cancel},SqliteDatabaseLimits::default())).unwrap_err();
        assert!(canceled&&error.contains("cancel"),"{error}");
        assert!(SemioObjectSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());
        assert!(SemioObjectSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
    }
}

#[test]
fn sqlite_snapshot_semio_object_distinct_alias(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for alias in f["distinctAliases"].as_array().unwrap(){let mut s=fixture();let child=s.mesh.as_mut().unwrap();child.child_id=alias["childId"].as_str().unwrap().into();child.target.artifact_id=alias["artifactId"].as_str().unwrap().into();let text=<SemioObjectSnapshot as store::ArtifactDsl>::print_dsl(&s);let binary=<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&s);assert_eq!(<SemioObjectSnapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap(),s);assert_eq!(<SemioObjectSnapshot as store::ArtifactPack>::decode_pack(&binary).unwrap(),s);let db=project(&s);let row=&db.table("semio_object_mesh_child").unwrap().rows[0];assert_eq!(row.text(2).unwrap(),alias["childId"].as_str().unwrap());assert_eq!(restore(&db).unwrap(),s);}}

#[test]
fn sqlite_snapshot_semio_object_native_transform_words(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for word in f["float64Bits"].as_array().unwrap(){let bits=u64::from_str_radix(word.as_str().unwrap(),16).unwrap();let mut s=fixture();s.transform.translation.x=f64::from_bits(bits);let text=<SemioObjectSnapshot as store::ArtifactDsl>::print_dsl(&s);let parsed=<SemioObjectSnapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap();assert_eq!(parsed.transform.translation.x.to_bits(),bits);let payload=store::os_io::IoPayload::Text(text);let parsed=SemioObjectSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(parsed.transform.translation.x.to_bits(),bits);}}

#[test]
fn sqlite_snapshot_semio_object_controlled_native_output(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let mut s=fixture();s.mesh.as_mut().unwrap().child_id="x".repeat(f["nativeOutputBytes"].as_u64().unwrap() as usize);s.mesh.as_mut().unwrap().target.artifact_id="remote!@/".into();for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let expected=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioObjectSnapshot as store::ArtifactDsl>::print_dsl(&s))};assert!(actual==expected,"controlled native output differs from the authored ordinary wire");let mut interior=false;let error=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |event|{let cancel=event.phase==SqliteSnapshotPhase::EncodeNative&&event.total>65536&&event.completed>=65536&&event.completed<event.total;interior|=cancel;!cancel},SqliteDatabaseLimits::default())).unwrap_err();assert!(interior&&error.contains("cancel"),"{error}");assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}}

#[test]
fn sqlite_snapshot_semio_object_all_transform_fields_erased_word_state(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let words=f["transformBits"].as_array().unwrap();assert_eq!(words.len(),10);let provider=store::ArtifactCodec::bare::<SemioObjectSnapshot,crate::standards::v1::subsets::object::schema::mutations::SemioObjectMutation>("s.stdio.semio.object").snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"object".into()};for offset in 0..words.len(){let mut s=fixture();let t=&mut s.transform;for(index,field)in [&mut t.translation.x,&mut t.translation.y,&mut t.translation.z,&mut t.rotation.x,&mut t.rotation.y,&mut t.rotation.z,&mut t.rotation.w,&mut t.scale.x,&mut t.scale.y,&mut t.scale.z].into_iter().enumerate(){*field=f64::from_bits(u64::from_str_radix(words[(index+offset)%words.len()].as_str().unwrap(),16).unwrap());}for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let expected=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioObjectSnapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioObjectSnapshot as store::ArtifactDsl>::print_dsl(&s))};let db=(provider.export)("s.stdio.semio.object",&dialect,&expected,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let db=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=(provider.import)("s.stdio.semio.object",&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(actual,expected,"field word rotation {offset} {encoding:?}");}}}
